import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Bart Verbruggen', position: 'GK', age: 24, club: 'Brighton', bio: {"es":"Verbruggen, que todavía tiene solo 23 años, ha sido la primera opción desde la Eurocopa de 2024, y el técnico Ronald Koeman se muestra relajado ante su relativa juventud. \"No estoy nada preocupado\", dijo. \"En Brighton está demostrando que puede manejar el más alto nivel\". El entrenador del Brighton, Fabian Hürzeler, está de acuerdo y destaca la creciente confianza del portero. \"Ahora hay una personalidad aún más fuerte entre los postes. Incluso sin el balón, su presencia es mucho mayor\". Verbruggen firmó su primer contrato profesional con el NAC Breda, pero nunca jugó en la Eredivisie holandesa, sino que logró su gran avance en Anderlecht. Luego vino el traslado de £ 16,3 millones a Inglaterra en 2023, una tarifa récord para un portero procedente de la máxima categoría belga. Su filosofía personal: “Lo más importante es ser honesto consigo mismo”, dijo al Athletic el año pasado. \"Mírate en el espejo. Mira lo que estás haciendo realmente bien, mira lo que quieres desarrollar y trabaja en ello con mucha alegría, trabajo duro y dedicación. La vida te devolverá lo que le des\".","en":"Verbruggen, still only 23, has been first choice since the 2024 Euros, with manager Ronald Koeman relaxed about his relative youth. “I’m not at all worried,” he said. “At Brighton he’s proving he can handle the highest level.” Brighton’s coach, Fabian Hürzeler, agrees, pointing to the keeper’s growing confidence. “There’s now an even stronger personality between the posts. Even without the ball, he’s becoming much more of a presence.” Verbruggen signed his first professional contract with NAC Breda, but never played in the Dutch Eredivisie, instead making his breakthrough at Anderlecht. Then came 2023’s £16.3m move to England, a record fee for a keeper moving from the Belgian top-flight. His personal philosophy: “The most important thing is to be honest with yourself,” he told the Athletic last year. “Look in the mirror. See what you’re doing really well, see what you want to develop and work on it with a lot of joy, hard work and dedication. Life will give you back what you give it.”"}, special: "No 1 goalkeeper" },
  { number: 13, name: 'Robin Roefs', position: 'GK', age: 23, club: 'Sunderland', bio: {"es":"El jugador de 23 años solo necesitó una temporada como portero titular en la Eredivisie para asegurar su paso a la Premier League. Y poco después de ese cambio del NEC al Sunderland el año pasado, Roefs recibió su primera convocatoria del seleccionador nacional, Ronald Koeman. “Todo está pasando muy rápido”, dijo el portero tras recibir la llamada. \"Se podría decir que estoy viviendo en un cuento de hadas\". Se unió al NEC a la edad de 11 años y, antes de despuntar como profesional, pasó años entrenando a porteros en su antiguo club amateur, Heeswijk. Como dejó el club de su ciudad natal a una edad tan temprana, no tenían derecho a ninguna compensación cuando hizo el gran traslado a Inglaterra, pero después de la mudanza, Roefs volvió a visitarlos y les entregó un cheque por valor de 25.000 euros. \"Heeswijk es el club donde empezó todo para mí\", dijo, \"y estoy feliz de poder dar algo a cambio\". El club respondió: \"La mayor parte del dinero irá a los jóvenes. Los jóvenes son el futuro. Robin es un verdadero modelo a seguir, y uno de nuestros porteros juveniles incluso recibió entrenamiento de Robin hoy. Fue un día verdaderamente maravilloso para nosotros\".","en":"The 23-year-old only needed one season as a first-choice keeper in the Eredivisie to secure a move to the Premier League. And shortly after that switch from NEC to Sunderland last year, Roefs was handed his first call-up by the national team coach, Ronald Koeman. “It’s all happening so fast,” the keeper said after getting the call. “You could say I’m living in a fairytale.” He joined NEC at the age of 11 and, before breaking through as a professional, spent years coaching keepers at his old amateur club Heeswijk. As he left his hometown club at such an early age they were not entitled to any compensation when he made the big transfer to England, but after the move Roefs went back to visit, and presented them with a cheque for €25,000. “Heeswijk is the club where it all started for me,” he said, “and I’m happy that I can now give something back.” The club said in response: “The majority of the money will go to the youth. The youth are the future. Robin’s a real role model, and one of our youth goalkeepers even received some training from Robin today. It was a truly wonderful day for us.”"} },
  { number: 23, name: 'Mark Flekken', position: 'GK', age: 33, club: 'Bayer Leverkusen', bio: {"es":"Un verdadero tardío. Flekken hizo su debut en la máxima categoría con el Friburgo a la edad de 25 años, después de pasar años jugando en las divisiones inferiores de Alemania, donde una vez marcó de tacón con el MSV Duisburg. En Friburgo llamó la atención del entrenador de la selección nacional, Louis van Gaal, en 2022, y aunque no pasó el corte para la Copa del Mundo ese año, Ronald Koeman lo nombró segunda opción para la Eurocopa 2024, después de haber impresionado en Inglaterra luego de su traslado de £ 11 millones a Brentford en 2023. Dejó Londres el año pasado para ir al Bayer Leverkusen, y Phil Giles, director de fútbol de Brentford, dijo: \"Esperábamos que Mark fuera nuestro portero durante muchos años más, pero... dejó claro que estaba interesado en mudarse más cerca de casa y con la posibilidad de jugar la Liga de Campeones\". Sufrió una lesión en la rodilla en enero, luego luchó por mantener la consistencia a su regreso, admitiendo en abril que su forma había sido irregular. \"Soy un excelente ejemplo de nuestro problema. Mis actuaciones no han sido consistentes. No tiene que ser un 10 sobre 10 en cada partido, o incluso un 8. Pero un promedio de 6,5 o 7, entonces eres un muy buen portero\".","en":"A real late bloomer. Flekken made his top-flight debut for Freiburg at the age of 25, after spending years playing in Germany’s lower divisions, where he once scored with a backheel for MSV Duisburg. At Freiburg he caught the eye of national team coach, Louis van Gaal, in 2022, and while he didn’t make the cut for the World Cup that year, he was named second-choice for Euro 2024 by Ronald Koeman, having impressed in England following 2023’s £11m move to Brentford. He left London last year for Bayer Leverkusen, with Phil Giles, Brentford’s director of football, saying: “We were expecting Mark to be our goalkeeper for many more years, but … he made it clear that he was interested in moving closer to home and with a possibility of Champions League football.” He sustained a knee injury in January, then struggled for consistency on his return, admitting in April his form had been patchy. “I'm a prime example of our problem. My performances haven't been consistent. It doesn't have to be a 10 out of 10 in every game, or even an 8. But an average of 6.5 or 7, then you're a very good keeper.”"}, special: "Late bloomer" },
  // Defensores
  { number: 2, name: 'Jurriën Timber', position: 'DF', age: 25, club: 'Arsenal', bio: {"es":"Uno de los mejores laterales derechos del mundo, se unió al Arsenal en 2023 por £ 34 millones procedente del Ajax, pero quedó fuera de juego en marzo debido a una lesión y tuvo que luchar duro para estar listo para la Copa del Mundo. Proviene de una fuerte familia futbolística: su hermano gemelo Quinten juega en el Marsella y uno de sus hermanos mayores juega en el VVV-Venlo de la segunda división del fútbol holandés. La fe juega un papel muy importante en su vida. El ex juvenil del Feyenoord y jugador del Ajax siempre lleva una Biblia a los partidos y lee el Salmo 91 antes del inicio, siguiendo el consejo de su madre. \"Ella me dijo: 'Lee esto antes de cada partido, te dará fuerzas'. Desde entonces lo he hecho y me ha dado éxito. Tomo todo lo que puedo de la Biblia y trato de vivir como vivió Jesús, aunque eso no siempre es fácil\". Utiliza su cuenta X para twittear los pasajes que lee a sus 226.000 seguidores. Ejemplo de tweet: “1 Tesalonicenses 5:8”","en":"One of the world’s best right-backs, he joined Arsenal in 2023 for £34m from Ajax, but was sidelined in March due to injury, and had to battle hard to be ready for the World Cup. He comes from a strong footballing family: his twin brother Quinten plays for Marseille, and one of his older brothers plays for VVV-Venlo in the second tier of Dutch football. Faith plays a very important role in his life. The former Feyenoord youth and Ajax player always takes a Bible with him to matches and reads Psalm 91 before kick-off, following his mother’s advice. “She told me: ‘Read this before every match, it will give you strength.’ Since then I’ve done that and it has brought success. I take as much as possible from the Bible and try to live as Jesus did, even though that isn’t always easy.” He uses his X account to tweet the passages he’s reading to his 226,000 followers. Sample tweet: “1 Thessalonians 5:8”"} },
  { number: 4, name: 'Virgil van Dijk', position: 'DF', age: 34, club: 'Liverpool', captain: true, bio: {"es":"La UEFA otorga el premio al Futbolista Europeo del Año desde 2011. Solo una vez el prestigioso premio ha recaído en un defensa: en 2019, cuando Virgil van Dijk venció a Lionel Messi y Cristiano Ronaldo. “Tuve que trabajar duro en cada paso del camino; eso es parte de mí y estoy muy feliz por ello”, dijo al aceptar el premio. \"Estoy muy orgulloso, todo el mérito es de todos los que me ayudaron en el camino\". Hijo de madre surinamesa y padre holandés, inicialmente fue criticado en las categorías inferiores del Willem II por considerarlo demasiado “relajado”. A través del FC Groningen, el Celtic y el Southampton, llegó al Liverpool en 2018. Un auténtico líder para el club y la selección, aunque en Holanda rara vez recibe el crédito que se merece, siendo muy apreciado en Inglaterra. Sin embargo, eso no es cierto en Willem II, donde el año pasado pusieron su nombre a un stand en sus instalaciones juveniles Sportpark Prinsenhoeve en Tilburg. El club afirmó: \"Con esto su nombre no sólo queda inmortalizado en la rica historia de Willem II, sino que también se vincula enfáticamente al desarrollo del fútbol juvenil en la ciudad\".","en":"Uefa has handed out the European Footballer of the Year award since 2011. Only once has the prestigious prize gone to a defender – in 2019, when Virgil van Dijk beat Lionel Messi and Cristiano Ronaldo. “I had to work hard for every step of the way – that's part of me and I'm very happy about that,” he said as he accepted the award. “I'm very proud, it's all credit to everyone that's helped me along the way.” The son of a Surinamese mother and Dutch father, he was initially criticised in the youth ranks at Willem II after being deemed too “laid-back”. Via FC Groningen, Celtic and Southampton, he arrived at Liverpool in 2018. A proper leader for club and country, even though in the Netherlands he still rarely gets the credit he deserves, being held in higher esteem in England. That’s not true back at Willem II, though, where they named a stand after him at their Sportpark Prinsenhoeve youth facility in Tilburg last year. The club said: “With this, his name is not only immortalised in the rich history of Willem II, but also emphatically linked to the development of youth football in the city.”"}, special: "Defensive rock" },
  { number: 5, name: 'Nathan Aké', position: 'DF', age: 31, club: 'Manchester City', bio: {"es":"El zurdo llevaba un tiempo indeciso sobre su identidad internacional. Nacido en la ciudad holandesa de Voorburg, de madre holandesa y padre marfileño, Aké jugó para equipos juveniles de Holanda y luego, en 2017, mantuvo varias conversaciones con el entrenador en jefe de Costa de Marfil, Marc Wilmots, sobre el cambio de lealtad. Pero cuando Dick Advocaat se convirtió en seleccionador de Holanda, rápidamente llamó a Aké, dándole su primera aparición internacional vinculante. Producto de las categorías inferiores de Feyenoord y Chelsea, lo ha ganado todo desde que llegó al Manchester City procedente de Bournemouth en 2020. Al igual que Stefan de Vrij, es un gran pianista y se dedicó a ello durante la pandemia de coronavirus. “Durante el primer confinamiento teníamos mucho tiempo libre, así que aprendí por mi cuenta con algunas aplicaciones”, le dijo al Telegraph. \"En el City, una vez toqué frente a los muchachos en Dortmund, en el hotel. Tuve una buena reacción, pero no me gusta que me vean demasiado. De hecho, también toqué en el funeral de mi padre, pero me resultó difícil, había demasiados ojos puestos en mí. Con el fútbol es diferente, estás acostumbrado, pero con el piano las manos empiezan a temblar y luego pierdes el ritmo y todo\".","en":"The left-footer spent some time undecided about his international identity. Born in the Dutch town of Voorburg to a Dutch mother and Ivorian father, Aké played for Netherlands youth teams, then in 2017 held several sets of talks with the Ivory Coast head coach Marc Wilmots about switching allegianc. But when Dick Advocaat became Netherlands manager, he swiftly called Aké up, giving him his first, binding international appearance. A product of the Feyenoord and Chelsea youth systems, he has won it all since joining Manchester City from Bournemouth in 2020. Like Stefan de Vrij, he’s a big pianist, having taken to it during the coronavirus pandemic. “In the first lockdown we had a lot of spare time, so I taught myself from a few apps,” he told the Telegraph. “At City, I’ve played in front of the guys once in Dortmund at the hotel. I got a good reaction, but I don’t like too many eyes on me. I actually played at my father’s funeral too, but I found it difficult – there were too many eyes on me. It’s different with football, you’re used to it, but with the piano your hands start to shake and then you lose the tempo and everything.”"} },
  { number: 6, name: 'Jan Paul van Hecke', position: 'DF', age: 25, club: 'Brighton', bio: {"es":"También conocido como \"el Gigante de Arnemuiden\", un apodo en honor a su paso por su club amateur local en la ciudad de Arnemuiden, en Zelanda. El robusto central fue adquirido por el Brighton procedente del NAC Breda hace seis años, pero su avance tardó algún tiempo, a través de cesiones en el club holandés Heerenveen y en la Championship con el Blackburn. Ahora, sin embargo, es un habitual de la Premier League y el año pasado ganó el premio al jugador del año de Brighton y también el premio al jugador del año de los jugadores. Es sobrino del ex internacional Jan Poortvliet, quien jugó en la final del Mundial de 1978 ante Argentina. Van Hecke dijo en 2024: \"Mi tío está disfrutando de mi viaje, dijo que está orgulloso y me mira cada partido. Cuando jugué contra el Ajax, ganar fuera de casa lo emocionó, estaba llorando... Me contó todas las historias del Mundial en el que jugó. ¡Dijo que les robaron contra Argentina!\".","en":"AKA “the Giant of Arnemuiden”, a nickname honouring his time at his local amateur club in the Zeeland town of Arnemuiden. The robust centre-back was snapped up by Brighton from NAC Breda six years ago but his breakthrough took some time, via loan spells at Dutch club Heerenveen and in the Championship with Blackburn. Now, though, he’s a Premier League regular, and last year won both Brighton’s player of the year award and the players’ player of the year too. He is the nephew of former international Jan Poortvliet, who played in the 1978 World Cup final loss to Argentina. Van Hecke said in 2024: “My uncle is enjoying my journey, he said he is proud and he watches me every game. When I played against Ajax, winning away made him emotional, he was in tears … He told me all the stories from the World Cup he played in. He said they were robbed against Argentina!”"}, special: "‘The Giant of Arnemuiden’" },
  { number: 15, name: 'Micky van de Ven', position: 'DF', age: 25, club: 'Tottenham', bio: {"es":"Uno de los futbolistas más rápidos del mundo. Van de Ven registró una velocidad máxima récord de la Premier League de 37,38 km/h (23,23 mph) contra Brentford en enero de 2024, y también ocupa las posiciones cuarta y quinta entre los cinco primeros. No siempre le resultó natural: en su primer club profesional, el FC Volendam, lo apodaron \"Tractor\" debido a sus movimientos torpes. “En ese momento pensaron que no era lo suficientemente bueno para el fútbol profesional”, dijo, “así que trabajé duro en mi agilidad y velocidad”. Ganó la Europa League con los Spurs el año pasado, pero llegó a la Copa del Mundo después de una temporada difícil luchando contra el descenso, y con el futuro de su club siendo objeto de muchas especulaciones. Lleva la camiseta número 37 en los Spurs y explicó el año pasado: \"Cuando tenía 15 años, teníamos un grupo cercano de amigos. Uno de nuestros mejores amigos se enfermó y lamentablemente no sobrevivió. Cuando estuve aquí en los Spurs para el día de mi fichaje, mi mejor amigo estaba conmigo. Estábamos los tres en ese entonces... Vimos que el número [37] estaba disponible y era un número especial para nuestro amigo que falleció\".","en":"One of the world’s fastest footballers. Van de Ven clocked a Premier League record top speed of 37.38km/h (23.23mph) against Brentford in January 2024 – and also occupies positions four and five in the top five. It didn’t always come naturally to him: at his first professional club, FC Volendam, he was nicknamed “Tractor” because of his awkward movement. “They thought at the time that I wasn’t good enough for professional football,” he said, “so I worked hard on my agility and speed”. He won the Europa League with Spurs last year, but arrived at the World Cup after a difficult season battling relegation, and with his club future the subject of plenty of speculation. He wears the number 37 shirt at Spurs, explaining last year: “When I was 15, we had a close group of friends. One of our best friends became ill, and he sadly did not survive. When I was here at Spurs for my signing day my best friend was with me. There were the three of us back then … We saw that number [37] was available and it was a special number to our friend who passed away.”"} },
  { number: 22, name: 'Denzel Dumfries', position: 'DF', age: 30, club: 'Inter', bio: {"es":"Dumfries, que lleva el nombre del actor estadounidense Denzel Washington por su padre de Aruba y su madre de Surinam, pasó muchos años jugando en clubes de aficionados y recién fue fichado por un equipo profesional, el Sparta Rotterdam, a la edad de 18 años. Tuvo que enfrentarse a los escépticos a lo largo de su carrera juvenil. \"Siempre fue difícil cuando se reían cuando dije que sería un profesional\", dijo a Sports Illustrated el año pasado. \"Para ser honesto, nunca pensé que llegaría tan lejos... He jugado a este nivel durante mucho tiempo. No es algo que esperaba cuando era más joven. Pero sabía que sería un jugador de fútbol profesional, lo sabía\". La experiencia moldeó su carácter, le ayudó a desarrollar una enorme resistencia y ritmo de trabajo, y le trajo un éxito considerable. Con el Inter ha acumulado numerosos trofeos importantes y es un jugador clave para esta selección holandesa. En 2014 jugó dos partidos amistosos con Aruba, pero dos años después pasó al equipo internacional holandés. En 2023, abrió junto con su familia un centro especializado de atención y educación juvenil en su ciudad natal, Rotterdam, para jóvenes que necesitaban apoyo especializado fuera de la educación general.","en":"Named after the American actor Denzel Washington by his Aruban father and Surinamese mother, Dumfries spent many years playing for amateur clubs and was only signed by a professional team, Sparta Rotterdam, at the age of 18. He had to face down the doubters throughout his youth career. “It was always tough when they were laughing when I said I’d be a pro,” he told Sports Illustrated last year. “To be honest, I never thought I would reach this far … I’ve played at this level for a very long time now. It’s not something I was expecting when I was younger. But I knew I would be a professional football player, I knew.” The experience shaped his character, helped him build tremendous stamina and work rate, and brought him considerable success. With Inter he has amassed numerous major trophies, and he’s a key player for this Netherlands side. In 2014 he played two friendly matches for Aruba, but switched to the Dutch international set-up two years later. In 2023, together with his family, he opened a specialist youth care and education centre in his home city of Rotterdam for young people needing specialist support outside mainstream education."} },
  { number: 25, name: 'Jorrel Hato', position: 'DF', age: 19, club: 'Chelsea', bio: {"es":"Considerado durante mucho tiempo como uno de los prospectos defensivos más brillantes de Europa, Hato fue capitán del Ajax a los 17 años y se mudó al Chelsea el año pasado por una tarifa inicial de £35,5 millones. Pero al principio le costó encontrar su lugar. “Mentiría si dijera que los primeros meses fueron fáciles, porque no lo fueron”, dijo en mayo. \"Fue un momento difícil, pero en la segunda mitad de la temporada viste mi mejor lado. He mostrado mis cualidades, las que mostré en el Ajax\". Su ex entrenador del club, Liam Rosenior, era un gran admirador y dijo: \"Me ha impresionado mucho su temperamento, su físico y técnicamente. Es un placer trabajar con él todos los días\". Hato es un gran admirador de Jurriën Timber del Arsenal, un compañero producto del Ajax. “Mis entrenadores siempre me dijeron que tenía que admirar a Virgil van Dijk, pero cuando jugaba en la sub-18, siempre admiraba a Jurriën Timber”, dijo Hato el año pasado. \"Jugué con él durante seis meses antes de que se fuera y aprendí mucho de él. Cuando entré en el primer equipo, él fue mi mentor\".","en":"Long considered one of the brightest defensive prospects in Europe, Hato captained Ajax at 17 and moved to Chelsea last year for an initial fee of £35.5m. But he struggled to find his feet at first. “I would lie if I say the first couple of months were easy, because they weren't,” he said in May. “It was a difficult time, but the second half of the season you saw the better side of me. I’ve showed my qualities, the ones I showed in Ajax.” His former club manager, Liam Rosenior, was a big fan, saying: “I've been so impressed with his temperament, his physicality, technically. He is a joy to work with every day.” Hato is a big fan of Arsenal’s Jurriën Timber, a fellow Ajax product. “My coaches always told me that I needed to look up to Virgil van Dijk, but when I played in the Under-18s, I always looked up to Jurriën Timber,” Hato said last year. “I played with him for six months before he left, and I learned so much from him. When I came into the first team, he was my mentor.”"} },
  // Volantes
  { number: 3, name: 'Marten de Roon', position: 'MF', age: 35, club: 'Atalanta', bio: {"es":"Cuando De Roon se perdió la Eurocopa 2024 por una lesión en la rodilla, parecía que su última oportunidad de participar en un gran torneo internacional se había esfumado. Pero aquí está, a sus 35 años, una de las varias elecciones sorpresa de Ronald Koeman. El centrocampista defensivo, que pasó una temporada con el Middlesbrough antes de regresar a su antiguo club, el Atalanta, en 2017, jugó su partido número 436 con el club de la Serie A en marzo, rompiendo su récord de más apariciones. Las cualidades que aporta son muy variadas: inteligencia táctica, carrera implacable y una gran personalidad, que se extiende a las redes sociales, donde es conocido por publicar memes autocríticos, Photoshop y sketches cómicos. Entre ellos se encontraba la viñeta de comedia de 2021 filmada en la tienda del club Atalanta, donde estuvo presente para firmar y pagar las primeras tres réplicas de camisetas de \"De Roon\" compradas en el mostrador. Nadie apareció antes de la hora de cierre, y se vio a De Roon haciendo un rompecabezas y jugando a las cartas mientras esperaba, diciendo: \"Apuesto a que Messi nunca tendrá que lidiar con esto\". Su biografía de perfil X dice: \"Resumen de jugar al fútbol en Italia: cuando ganamos, obtengo la mejor mesa y la comida gratis. Cuando perdemos, mi esposa tiene que ir a recogerlo\".","en":"When De Roon missed Euro 2024 with a knee injury it looked like his last shot at a big international tournament had gone. But here he is, at 35, one of several surprise picks by Ronald Koeman. The defensive midfielder, who had a season with Middlesbrough before returning to his former club Atalanta in 2017, played his 436th game for the Serie A club in March, breaking their record for most appearances. The qualities he brings are wide-ranging: tactical intelligence, relentless running and a big personality, which extends to social media, where he’s known for posting self-deprecating memes, Photoshops and comedy skits. Among them was 2021’s comedy vignette filmed in the Atalanta clubshop where he was on hand to sign and pay for the first three \"De Roon\" replica shirts purchased over the counter. Nobody turned up before closing time, with De Roon seen doing a jigsaw and playing cards while he waited, saying: “I bet Messi never has to deal with this.” His X profile biog reads: “Summary of playing football in Italy: when we win I get the best table and the food for free. When we lose, my wife has to go and pick it up.”"} },
  { number: 8, name: 'Ryan Gravenberch', position: 'MF', age: 24, club: 'Liverpool', bio: {"es":"Gravenberch firmó un nuevo contrato a largo plazo con Liverpool en marzo, lo que refleja su enorme mejora en Anfield desde que llegó procedente del Bayern en 2023. Con solo 24 años, su futuro parece brillante, y mucho más brillante que, durante un tiempo, en Múnich. Su padre, Ryan Sr, reveló a principios de esta temporada que a su hijo le costó mucho adaptarse cuando llegó por primera vez a Alemania, razón por la cual se mudaron allí para apoyarlo. \"El mundo del fútbol es duro\", dijo su padre. \"Ryan sólo tenía 21 años en ese momento y tenía muchos problemas. El traslado al Liverpool fue lo mejor que le pudo pasar: pasó de ese infierno a su cielo\". De niño aprendió mucho de su hermano Danzell, que es ocho años mayor. \"Cuando era pequeño lo veía jugar afuera\", le dijo a The Guardian en 2024, \"y cuando éramos un poco mayores iba con él a jugar a la calle. Es un niño grande, así que fue difícil para mí, pero él me endureció\". Danzell tuvo su propia carrera futbolística nómada, jugando para 13 clubes, mientras que Ryan se convirtió en el jugador más joven del Ajax cuando debutó con 16 años y 130 días.","en":"Gravenberch signed a new long-term deal at Liverpool in March, reflecting his massive improvement at Anfield since joining from Bayern in 2023. Still only 24, his future looks bright – and much brighter than it had, for a time, in Munich. His father, Ryan Sr, revealed earlier this season that his son struggled badly to adjust when he first arrived in Germany, which is why they moved out there to support him. “The football world is hard,” his dad said. “Ryan was only 21 at that time and had a lot of problems. The move to Liverpool was the best thing that could happen: he went from that hell to his heaven.” As a child he learned a lot from his brother Danzell, who is eight years older. “When I was little I watched him play outside,” he told The Guardian in 2024, “and when we were a bit older I would go with him to play on the streets. He’s a big boy so it was difficult for me, but he toughened me up.” Danzell went on to have a nomadic football career of his own, playing for 13 clubs, while Ryan became Ajax’s youngest ever player when he made his debut aged 16 years and 130 days."} },
  { number: 12, name: 'Mats Wieffer', position: 'MF', age: 27, club: 'Brighton', bio: {"es":"La convocatoria de Wieffer fue una sorpresa. A pesar de haber jugado 14 partidos internacionales, no había aparecido en las cuatro ventanas internacionales anteriores. Pero el director de su club, Fabian Hürzeler, fue uno de sus mayores defensores de la retirada, destacando su enorme versatilidad. \"Tiene muy buen físico, una buena comprensión del juego... es un jugador de equipo absoluto\". Wieffer fichó procedente del Feyenoord en 2024 por 25,4 millones de libras esterlinas, lo que lo convirtió en la venta récord del equipo de la Eredivisie. Sin embargo, no quedó tan impresionado cuando llegó por primera vez a Brighton. \"Era verano, pero el tiempo era terrible: gris, lluvia, viento. Estaba en un hotel con mi familia y pensé seriamente: ¿dónde he acabado?\". le dijo al medio holandés tubantia.nl en marzo. \"Pero mis padres se quedaron un poco más después de que me fui, y al día siguiente el clima de repente era hermoso. Me enviaron fotos y pensé: Bueno, esta es una ciudad completamente diferente\". También le encantan los helados del paseo marítimo. \"Tienen los mejores helados del sur de Inglaterra. Tan buenos como los de Van der Poel en Hengelo, pero mucho más grandes. Una bola es suficiente\".","en":"Wieffer’s call-up was a bit of a surprise. Despite having 14 caps he hadn’t featured in the previous four international windows. But his club manager, Fabian Hürzeler, was among his biggest cheerleaders for a recall, pointing out his huge versatility. “He has a really good physicality, a good understanding of the game … he's an absolute team player.” Wieffer signed from Feyenoord in 2024 for a reported £25.4m, making him the Eredivisie side’s record sale. He wasn’t that impressed when he first arrived in Brighton, though. “It was summer, but the weather was terrible: grey, rain, wind. I was in a hotel with my family and seriously thought: where on earth have I ended up?” he told Dutch outlet tubantia.nl in March. “But my parents stayed a bit longer after I left, and the next day the weather was suddenly beautiful. They sent me photos and I thought: OK, this is quite a different city.” He has grown to love the ice cream on the sea-front, too. \"They have the best ice creams in South England. Just as good as at Van der Poel in Hengelo, but much bigger. One scoop is enough.\""}, special: "Ice cream lover" },
  { number: 14, name: 'Tijjani Reijnders', position: 'MF', age: 28, club: 'Manchester City', bio: {"es":"Los padres de Reijnders eran grandes admiradores del ex gran jugador del Ajax, Tijani Babangida, por lo que elegir el nombre de su bebé fue fácil. Su madre incluso se aseguró de usar la doble j en Tijjani: la escritura correcta del nombre de Babangida en su pasaporte, en lugar de la versión registrada incorrectamente cuando Babangida se mudó a los Países Bajos en 1991. El año pasado, los dos hombres finalmente se conocieron, cuando Babangida le dio a Reijnders una copia firmada de su autobiografía. El padre de Reijnders, Martin, también fue futbolista y actualmente fabrica pizarras tácticas, mientras que el hermano de Reijnders, Eliano, juega en el club indonesio Persib Bandung y, gracias a la nacionalidad de su madre, en la selección nacional de Indonesia. Reijnders se unió al Manchester City por £ 46,5 millones procedente de Milán en junio del año pasado, un viaje desde su antiguo trabajo a tiempo parcial en su Aldi local, que hizo cuando era joven en Zwolle. En 2023, dijo: \"Solía ​​abastecer las estanterías, trabajar detrás de la caja y ganar unos cientos de euros al mes... mi tiempo en Aldi fue realmente bueno para mí. He visto ambas caras de la moneda\".","en":"Reijnders’ parents were massive fans of the former Ajax great Tijani Babangida, so choosing what to name their baby was easy. His mum even made sure to go with the double j in Tijjani – the correct spelling of Babangida’s first name on his passport, rather than the version wrongly registered when Babangida moved to the Netherlands in 1991. Last year the two men finally met, when Babangida gave Reijnders a signed copy of his autobiography. Reijnders’ dad, Martin, was also a footballer, and these days manufactures tactical whiteboards, while Reijnders’ brother Eliano plays for Indonesian club Persib Bandung and, thanks to his mum’s nationality, the Indonesian national team. Reijnders joined Manchester City for £46.5m from Milan in June last year – some journey from his old part-time job in his local Aldi, which he did while he was a youngster at Zwolle. In 2023 he said: \"I used to stock the shelves, work behind the till and earn a few hundred euros a month … my time at Aldi was really good for me. I've seen both sides of the coin.\""} },
  { number: 16, name: 'Guus Til', position: 'MF', age: 29, club: 'PSV Eindhoven', bio: {"es":"Nacido en Zambia, la familia de Til se mudó a Ámsterdam cuando él tenía tres años. Se crió en el sistema juvenil del AZ y se convirtió en un mediocampista ofensivo sólido que también puede hacer un trabajo en la delantera. Es un jugador poco convencional y ha tenido detractores, pero no le molestan. \"Creo que es una tontería cuando la gente dice que no soy bueno con la pelota... ¿Y por qué tiene que verse bien de todos modos? No me considero un futbolista hermoso; soy bastante desgarbado. ¿Alguna vez has visto a Medvedev jugar tenis? Parece que tiene un matamoscas en la mano. Pero es uno de los mejores jugadores de tenis del mundo\". Hablando antes de su llamada sorpresa por parte de Ronald Koeman, le dijo a De Volkskrant: \"Es bueno que esté pensando en mí. Pero si sucede, no quiero que parezca que voy como un turista. Quiero ir porque puedo jugar bien al fútbol. No me voy a sentar en el banquillo sólo por diversión\". Pase lo que pase con Til este verano, no esperes que te lo cuente: realmente no le gustan las entrevistas. \"No, no me gustan, para nada. Otros pueden hablar de mí, lo demostraré en el campo\".","en":"Born in Zambia, Til’s family moved to Amsterdam when he was three. He was raised in AZ’s youth system, and grew into a solid attacking midfielder who can also do a job up front. He’s an unconventional player, and he has had his detractors – but he isn’t bothered by them. “I think it’s nonsense when people say I’m not good on the ball… And why does it have to look good anyway? I don’t consider myself a beautiful footballer; I’m quite gangly. Have you ever seen Medvedev play tennis? It looks like he has a fly-swatter in his hand. But he is one of the best tennis players in the world.” Speaking before his surprise call-up by Ronald Koeman he told de Volkskrant: “It is nice he is thinking about me. But if it happens, I don’t want it to look like I’m going along as a tourist. I want to go because I can play football well. I’m not going to sit on the bench just for the fun of it.” Whatever happens for Til this summer, don’t expect him to tell you about it: he really doesn’t like interviews. “No, I don’t like them, not at all. Others can talk about me, I’ll show it on the field.”"}, special: "Surprise call-up" },
  { number: 20, name: 'Teun Koopmeiners', position: 'MF', age: 28, club: 'Juventus', bio: {"es":"Cuando eran niños, a Teun y su hermano pequeño Peer les encantaba la serie de libros sobre fútbol Koen Kampioen del escritor holandés Fred Diks. Inspirados por las historias, ambos crecieron hasta convertirse en profesionales (Peer juega en el AZ Alkmaar) y ahora colaboran con Diks en su propia serie de aventuras futbolísticas. Teun tendrá muchas historias para compartir. Antes del traslado de £ 46 millones de Atalanta a Juventus en 2024, donde en ocasiones tuvo problemas y fue criticado por los fanáticos, estaba fuertemente vinculado con el Liverpool. Pero Peer dijo el año pasado que Teun no se arrepentía de la decisión de quedarse en Italia en lugar de presionar para mudarse a Inglaterra. \"Teun ama a la Juve. Como su hermano, puedo decirles que nunca lo había visto tan feliz como en las fotos que me envió el día de su presentación. Su cara lo decía todo; nunca antes había visto ese tipo de felicidad en él\". Teun hizo su debut internacional en 2020, pero se perdió la Eurocopa 2024 debido a una lesión.","en":"As children, Teun and his little brother Peer both loved the Koen Kampioen series of football books by Dutch writer Fred Diks. Inspired by the stories, they both grew up to be professionals – Peer plays for AZ Alkmaar – and are now collaborating with Diks on their own series of football adventures. Teun will have plenty of stories to share. Before 2024’s £46m move from Atalanta to Juventus, where he has struggled at times and been criticised by fans, he was heavily linked with Liverpool. But Peer said last year that Teun had no regrets about the decision to stay in Italy rather than push for a move to England. “Teun loves Juve. As his brother, I can tell you I had never seen him as happy as he was in the photos he sent me on the day of his presentation. His face said it all – I had never seen that kind of happiness on him before.” Teun made his international debut in 2020 but missed Euro 2024 because of injury."} },
  { number: 21, name: 'Frenkie de Jong', position: 'MF', age: 28, club: 'Barcelona', bio: {"es":"Cuando era joven en la cantera del Ajax, a De Jong se le encomendó una vez la tarea de proporcionar oposición a los jugadores del primer equipo durante una sesión de entrenamiento. En lugar de mantener la cabeza gacha y recostarse, comenzó a driblar alrededor de ellos y anotar, hasta que el entrenador le gritó que parara. Fue un vistazo de lo que estaba por venir. Paris St-Germain, Manchester City y Manchester United hicieron movimientos por él antes de que dejara el Ajax en 2019, pero su corazón estaba puesto en Barcelona. Cuando era niño, él y su familia solían pasar sus vacaciones a 80 kilómetros de la ciudad, en un camping cerca de L'Escala. “Esas vacaciones fueron geniales”, recordó poco después de sellar la transferencia de 75 millones de euros. \"Había tres campos de fútbol en el camping. Un verano incluso fuimos a ver un amistoso del Barça. Recuerdo a Ronaldinho jugando y fue increíblemente emocionante verlo en vivo\". Hoy en día, es una de las leyendas. Lleva la camiseta número 21 como homenaje a su abuelo. \"Llevé a toda mi familia a mi presentación en Barcelona\", dijo en 2019, \"excepto a mi abuelo Hans de Jong, el padre de mi padre. Murió el día de mi cumpleaños número 21. Es una especie de homenaje. Era un gran aficionado al fútbol\".","en":"As a youngster in Ajax’s youth system De Jong was once tasked with providing some opposition for first-team players during a training session. Instead of keeping his head down and sitting back, he started dribbling around them and scoring, until the coach shouted at him to stop. It was a glimpse of what was to come. Paris St-Germain, Manchester City and Manchester United all made moves for him before he left Ajax in 2019, but his heart was set on Barcelona. As a boy he and his family used to holiday 50 miles away from the city on a campsite near L’Escala. “Those holidays were great,” he recalled, soon after sealing the €75m transfer. “There were three football pitches on the campsite. One summer, we even went to watch a Barça friendly. I remember Ronaldinho playing and it was incredibly exciting to watch him live.” These days, he is one of the legends. He wears the No 21 shirt as a tribute to his grandfather. “I brought my whole family to my presentation in Barcelona,” he said in 2019, “except my grandfather Hans de Jong, my father's father. He died on the day of my 21st birthday. It is kind of a tribute. He was a huge football fan.\""}, special: "Midfield maestro" },
  { number: 26, name: 'Quinten Timber', position: 'MF', age: 25, club: 'Marseille', bio: {"es":"El gemelo de Jurrien. En realidad, no es tan inusual que dos hermanos jueguen para Holanda; otros ejemplos incluyen a Frank y Ronald de Boer, Willy y René van der Kerkhof, Rob y Richard Witschge y, por supuesto, el seleccionador nacional Ronald Koeman y su ahora asistente Erwin. Los gemelos Timber también tienen tres hermanos mayores: Dylan, defensa del club holandés VVV-Venlo y de la selección nacional de Curazao, además de Shamier y Chris. En 2019, Chris habló sobre los problemas que plantea el desarrollo de los gemelos como jugadores jóvenes. \"Siempre me costó diferenciarlos. Yo diría que Quinten había hecho un buen movimiento, pero mi madre decía que era Jurriën. También tenían el mismo peinado, lo que tampoco ayudó. Ahora, uno es un poco más alto y el otro tiene la cabeza un poco más redonda\". Quinten llegó al Mundial después de una temporada difícil cuando se peleó con el técnico del Feyenoord, Robin van Persie, tras rechazar un nuevo contrato. Pero su traslado a Marsella en enero le permitió demostrar que está preparado para este verano.","en":"Jurrien’s twin. It’s not actually that unusual for two brothers to play for the Netherlands - other examples include Frank and Ronald de Boer, Willy and René van der Kerkhof, Rob and Richard Witschge and, of course, national coach Ronald Koeman and his now-assistant Erwin. The Timber twins also have three older brothers: Dylan, a defender for Dutch club VVV-Venlo and the Curaçao national team, plus Shamier and Chris. In 2019 Chris spoke about the issues watching the twins develop as young players. “I always had trouble telling them apart. I would say that Quinten had made a nice move, but my mother would say it was Jurriën. They also had the same hairstyle, which didn't help either. Now, one is a bit taller and the other has a slightly rounder head.” Quinten arrived at the World Cup after a difficult season when he fell out with Feyenoord coach, Robin van Persie, after refusing a new contract. But his move to Marseille in January allowed him to prove his readiness for this summer."} },
  // Delanteros
  { number: 7, name: 'Justin Kluivert', position: 'FW', age: 27, club: 'Bournemouth', bio: {"es":"Definitivamente ayuda, como joven que se abre camino en el juego, si tu padre era un ícono global que tiene los números de teléfono de los mejores entrenadores y jugadores. Fue una llamada entre su padre Patrick y la leyenda de la Roma Francesco Totti lo que llevó a Kluivert a pasar del Ajax a la Roma en 2018. Pasó cinco años en sus libros, aunque tres de ellos estuvieron cedido en RB Leipzig, Niza y Valencia, antes de ser vendido a Bournemouth en 2023. Ese fue el momento en que su carrera realmente despegó y se ganó un lugar de regreso en la selección nacional, después de haber debutado por primera vez en 2018. “Estoy orgulloso de volver a vestir la camiseta de Holanda”, dijo después de la destitución. \"Me siento mucho mejor, tanto dentro como fuera del campo, en Inglaterra. Me siento muy feliz jugando en el Bournemouth\". Su grave lesión durante el invierno le hacía duda para este verano, pero Ronald Koeman siempre dijo que le incluiría si demostraba su forma física.","en":"It definitely helps, as a youngster making your way in the game, if your dad was a global icon who has the phone numbers of top managers and players. It was a call between his dad Patrick and Roma legend Francesco Totti that led to Kluivert’s 2018 move from Ajax to Roma. He spent five years on their books, though three of them were on loan at RB Leipzig, Nice and Valencia, before he was sold to Bournemouth in 2023. That was the moment his career really took off and he earned a place back in the national team, having first made his debut in 2018. “I’m proud to wear the shirt of the Netherlands again,” he said after the recall. “I feel so much better, both on and off the pitch, in England. I feel so happy playing for Bournemouth.” His serious injury over the winter made him a doubt for this summer, but Ronald Koeman always said he would include him if he could prove his fitness."} },
  { number: 9, name: 'Wout Weghorst', position: 'FW', age: 33, club: 'Ajax', bio: {"es":"Argentina no querrá enfrentarse a Holanda en este Mundial. Si esto sucede, Weghorst estará listo para ir a la guerra nuevamente. El delantero de 1,98 m demostró su valor como supersuplente durante la última Copa del Mundo cuando cambió el juego contra Argentina, anotando dos goles y llevando a los holandeses a la prórroga. Pero toda su agresividad en el campo y en el túnel –que terminó en una guerra de palabras con Lionel Messi, que gritó “¿Qué miras, bobo? Andá pa' allá, bobo”— dejó a los argentinos furiosos. Un verdadero estafador, Weghorst ascendió en la escala del fútbol, ​​apoyado por su padre millonario, hasta llegar al club de sus sueños, el Manchester United. Pero en sus seis meses cedido por el Burnley en 2023, solo logró dos goles en 31 apariciones, ninguno en la liga. Se ganó un apodo cariñoso en Old Trafford por parte de sus compañeros, quienes lo llamaban Bobo, en honor al incidente de Messi. No fue un habitual en el Ajax la temporada pasada, pero Ronald Koeman aún estará listo para usarlo desde el banco para cambiar de juego este verano.","en":"Argentina won’t want to face the Netherlands at this World Cup. If it happens, Weghorst will be ready to go to war again. The 1.98m striker proved his value as a supersub during the last World Cup when he changed the game against Argentina, scoring twice and leading the Dutch to extra time. But all his aggression on the pitch and in the tunnel – ending with a war of words with Lionel Messi who shouted “Qué mirás, bobo? Andá pa' allá, bobo” (\"What are you looking at, fool? Go away, fool”) – left the Argentinians steaming. A real grafter, Weghorst climbed the football ladder, supported by his millionaire father, all the way to his dream club, Manchester United. But in his six months there on loan from Burnley in 2023 he only managed two goals in 31 appearances, none in the league. He earned an affectionate nickname at Old Trafford from his teammates, who called him Bobo, in honour of the Messi incident. He wasn’t a regular at Ajax last season, but Ronald Koeman will still be ready to use him from the bench to change games this summer."} },
  { number: 10, name: 'Memphis Depay', position: 'FW', age: 32, club: 'Corinthians', bio: {"es":"Memphis inicialmente jugó con el nombre Depay en la parte posterior de su camiseta, pero en 2012 decidió abandonar el apellido de su padre, porque había abandonado a la familia cuando su hijo tenía cuatro años. Una infancia difícil se ha reflejado en un comportamiento a veces errático. Fue famoso por las críticas de grupos de derechos animales en 2020 cuando publicó fotos de él mismo con una cría de ligre, un cruce entre un león y un tigre. También es conocido por su moda, su carrera musical, su diadema blanca en juego y su habilidad para moverse, parándose sobre el balón con ambos pies. Lo hizo durante un partido del Corinthians contra Palmeiras el año pasado, lo que resultó en una pelea masiva. La Federación Brasileña de Fútbol dijo más tarde que la medida sería una infracción con tarjeta amarilla en el futuro, porque representa \"una provocación a un rival y una falta de respeto al juego\". El documental Con ambos pies mostró otra faceta de él, centrada en la enorme fuerza de voluntad que necesitó para recuperarse de una lesión del ligamento cruzado en 2019. Después de períodos mixtos en Europa, incluidos Manchester United y Barcelona, ​​se mudó a Brasil en 2024. Durante las eliminatorias para el Mundial dejó su pasaporte en su casa en Brasil, perdió su vuelo y llegó tarde. Típico de Memphis, dijeron sus críticos. Pero sigue siendo el máximo goleador de todos los tiempos de la selección nacional y una parte valiosa de este equipo.","en":"Memphis initially played with the name Depay on the back of his shirt, but in 2012 decided to drop his father’s surname, because he had walked out on the family when his son was four. A difficult childhood has been reflected in sometimes erratic behaviour. He famously drew criticism from animal rights groups in 2020 when he posted photos of himself with a baby liger, a cross between a lion and a tiger. He’s also known for his fashion, his music career, his in-play white headband and his skill move, standing on the ball with both feet. He did it during a Corinthians game against Palmeiras last year, resulting in a mass brawl. Brazil’s FA later said the move would be a yellow card offence in future, because it represents “provocation to a rival, and disrespects the game”. The documentary With Both Feet showed another side of him, centred on the enormous willpower it took to recover from a cruciate ligament injury in 2019. After mixed spells in Europe, including Manchester United and Barcelona, he moved to Brazil in 2024. During the World Cup qualifiers he left his passport at home in Brazil, missed his flight and arrived late. Typical Memphis, said his critics. But he remains the national side’s all-time top scorer, and a valuable part of this squad."}, special: "Record goalscorer" },
  { number: 11, name: 'Cody Gakpo', position: 'FW', age: 26, club: 'Liverpool', bio: {"es":"La religión juega un papel importante en la vida y carrera de Gakpo. Escucha música gospel en su coche, con The Blessing de la cantante Eline Bakker entre sus favoritas; a menudo lleva una camiseta que dice \"Pertenezco a Jesús\" debajo de la camiseta, como lo hizo famoso su ídolo del fútbol Kaká; Dirigió un grupo bíblico en el equipo holandés en la última Copa del Mundo y ora antes de los partidos. \"Si no puedo ir a la iglesia, llamo al pastor\", dijo al periódico holandés NRC. \"La fe me da paz. Y fuerza cuando la necesito. A menudo leo la Biblia antes de irme a dormir. Es una especie de carta de amor que nos dice cómo debemos tratarnos unos a otros\". Se unió al Liverpool procedente del PSV en 2023 por 37 millones de libras iniciales y firmó un nuevo contrato a largo plazo el año pasado. En su tiempo libre, es un gran lector. “Leo principalmente libros sobre psicología, fe y mentalidad”, dijo Gakpo a Algemeen Dagblad. \"El pensamiento de caja negra [de Matthew Syed] se trata de cometer errores... Si creas una cultura en la que admitir tus errores es clave, la gente se desarrollará más. Intento trasladar esto al campo de fútbol\".","en":"Religion plays a big part in Gakpo’s life and career. He listens to gospel music in his car, with The Blessing by singer Eline Bakker among his favourites; he often wears an “I belong to Jesus” T-shirt under his top, as made famous by his football idol Kaka; he led a Bible group in the Dutch squad at the last World Cup and he prays before games. “If I can’t go to church, I call the pastor,” he told Dutch paper NRC. “Faith gives me peace. And strength when I need it. I often read the Bible before I go to sleep. It is a kind of love letter that tells us how we should treat each other.” He joined Liverpool from PSV in 2023 for an initial £37m, and signed a new long-term deal last year. In his spare time, he’s a big reader. “I mainly read books about psychology, faith and mindset,” Gakpo told Algemeen Dagblad. “Black Box Thinking [by Matthew Syed] is about making mistakes … If you create a culture where admitting your mistakes is key, people will develop more. I try to translate this to the football pitch.”"} },
  { number: 17, name: 'Noa Lang', position: 'FW', age: 27, club: 'Napoli', bio: {"es":"Ha sido un viaje animado hasta ahora. El polémico lateral ha pasado por seis clubes en las últimas cinco temporadas. Sus compañeros de la selección lo llaman “problema”. Pero Lang demostró varias veces que puede jugar un gran fútbol y que nunca le falta confianza en sí mismo. Cuando dejó Bélgica, donde jugaba en el Club Brujas, dijo: \"Hice que el fútbol belga se calentara. Sinceramente, lo creo. Créanme: Bélgica me va a extrañar cuando me vaya. Rezarán para que haya un nuevo Noa Lang\". Y en 2022, después de una actuación goleadora con la selección nacional, dijo: \"¿Estaba nervioso? No. Juego en la selección holandesa porque sé jugar bien al fútbol. ¿Por qué debería estar nervioso por algo que puedo hacer muy bien? Cuando se le preguntó si le habían animado a bajar un poco el tono, dijo: “Así soy yo. Noa Lang está siendo entrevistado, luego obtendrás a Noa Lang... Me gusta simplemente decir lo que pienso.\" Este verano rivalizará con Cody Gakpo por el puesto de izquierda.","en":"It’s been a lively journey so far. The controversial winger has had six clubs in the last five seasons. His teammates in the national squad call him “trouble”. But Lang proved several times that he can play great football, and never lacks self-belief. When he left Belgium, where he played for Club Brugge, he said: “I made Belgian football hot. I honestly think so. Believe me: Belgium is going to miss me when I'm gone. They are going to pray there will be a new Noa Lang.’’ And in 2022, after a scoring display for the national side, he said: “Was I nervous? No. I play in the Dutch national team because I can play football well. Why should I be nervous about something I can do very well?” Asked if he had been encouraged to tone it down a bit, he said: “This is how I am. Noa Lang is being interviewed, then you will get Noa Lang … I like to just say what I think.\" This summer he will rival Cody Gakpo for the left-wing position."}, special: "Maverick" },
  { number: 18, name: 'Donyell Malen', position: 'FW', age: 27, club: 'Roma', bio: {"es":"Dejar el Aston Villa cedido por la Roma el año pasado definitivamente valió la pena. Malen anotó 10 goles en sus primeros 12 partidos de la Serie A, igualando el récord de Gabriel Batistuta del año 2000. \"Estoy muy orgulloso de la comparación con Batistuta\", dijo. \"He visto muchos vídeos de él; era un gran jugador. Mi objetivo es seguir marcando cada vez más\". Hizo el movimiento en parte en un intento por mantener su lugar en la selección nacional, porque estaba luchando por tener inicios regulares en Villa. Comenzó en la cantera del Ajax antes de mudarse al Arsenal en 2015, pero regresó a Holanda con el PSV dos años después. Se mudó a la Bundesliga con el Borussia Dortmund en 2021 y a Villa, por £ 21 millones, el año pasado. Es probable que Ronald Koeman utilice a Malen como su delantero este verano si Memphis Depay lucha contra las lesiones. En caso contrario, Malen jugará de banda. Su filosofía personal: \"Soy un delantero. Intento crear, marcar goles, dar asistencias y simplemente animar al estadio. Intentar hacer cosas especiales\".","en":"Leaving Aston Villa for Roma on loan last year definitely paid off. Malen scored 10 goals in his first 12 Serie A games, matching Gabriel Batistuta’s record from 2000. “I am very proud of the comparison with Batistuta,” he said. “I’ve seen so many clips of him; he was a great player. My objective is to keep scoring more and more.” He made the move partly in a bid to keep his spot in the national team, because he was struggling for regular starts at Villa. He started out in Ajax’s youth system before moving to Arsenal in 2015, but returned to the Netherlands with PSV two years later. He moved to the Bundesliga with Borussia Dortmund in 2021, and to Villa, for £21m, last year. Ronald Koeman is likely to use Malen as his striker this summer if Memphis Depay struggles with injuries. If not, Malen will play on the wing. His personal philosophy: “I'm a forward. I try to create, score goals, give assists and just give the stadium a buzz. Try to do special things.”"} },
  { number: 19, name: 'Brian Brobbey', position: 'FW', age: 24, club: 'Sunderland', bio: {"es":"Después de una temporada decepcionante en el Ajax, el lugar de Brobbey en este equipo mundialista parecía a años luz de distancia. Pero su traslado de £17,3 millones al Sunderland cambió todo eso, ya que mostró su físico, movimiento y capacidad para dominar a los defensores de la Premier League. Sin embargo, no siempre ha hecho los movimientos profesionales más inteligentes. Al principio dejó el Ajax, tentado por el RB Leipzig, pero regresó poco después. \"Fue una dura lección para mí\", dijo. \"Si me hubiera quedado en el Ajax, habría sido mucho mejor para mi desarrollo\". Su regreso no fue fácil al principio: faltaron goles y luego, en octubre de 2023, se vio involucrado en un horrible choque con el portero del RKC Waalwijk, Etienne Vaessen, que quedó inconsciente. El partido fue suspendido y Vaessen estuvo fuera de acción durante semanas. Cuando finalmente se jugaron los últimos 10 minutos del partido en diciembre de ese año, con Vaessen nuevamente en la portería, la pareja intercambió abrazos. Vaessen dijo: \"El contacto frecuente con Brian [durante mi recuperación] nos hizo bien a mí y a mi familia. No le guardé nada contra él. Es un buen tipo y me dio su camiseta para mi hijo. Mi hijo es un fan total de Brobbey\".","en":"After a disappointing season at Ajax, Brobbey’s place in this World Cup squad seemed light years away. But his £17.3m move to Sunderland changed all that, as he showcased his physicality, movement and ability to dominate Premier League defenders. He hasn’t always made the most clever career moves, though. Early on he left Ajax, tempted by RB Leipzig, but came back soon after. “It was a hard lesson for me,” he said. “If I had stayed at Ajax it would have been much better for my development.” His return didn’t go smoothly at first: goals were lacking, and then, in October 2023, he was involved in a horrible collision with RKC Waalwijk goalkeeper Etienne Vaessen who was left unconscious. The match was abandoned and Vaessen was out of action for weeks. When the final 10 minutes of the game were eventually played out in December that year, with Vaessen back in goal, the pair exchanged hugs. Vaessen said: “The frequent contact with Brian [during my recovery] did me and my family good. I didn't hold anything against him. He is a nice guy, and he gave me his shirt for my son. My son is a total Brobbey fan.”"} },
  { number: 24, name: 'Crysencio Summerville', position: 'FW', age: 25, club: 'West Ham', bio: {"es":"Fue una temporada sombría para el West Ham, pero un puñado de jugadores salieron airosos de ella, y Summerville estaba entre ellos. Después de fichar procedente del Leeds por 25 millones de libras esterlinas en agosto de 2024, su primera temporada se vio gravemente interrumpida por una lesión en el tendón de la corva. Pero la temporada pasada estuvo en el centro de muchos de los mejores momentos del equipo. Cuando se confirmó el descenso, publicó en línea: \"El West Ham United es demasiado grande, demasiado especial y demasiado poderoso para permanecer abajo por mucho tiempo. La remontada comienza ahora\". Pero aún está por verse si será parte de ese intento de regreso; Muchos clubes rivales han mostrado interés. Nacido en Rotterdam, se unió a la academia del Feynoord en 2008 y llamó la atención durante una cesión en el ADO Den Haag. Fuera del fútbol, ​​es un gran aficionado al baloncesto. “Me encanta jugar en una cancha de baloncesto porque me encanta ver la NBA”, dijo en 2024. “Mis jugadores favoritos son LeBron James y Stephen Curry, ambos grandes de todos los tiempos, y siempre trato de replicar sus tiros cuando estoy en la cancha”.","en":"It was a grim season for West Ham, but a handful of players came out of it with credit, and Summerville was among them. After signing from Leeds for £25m in August 2024, his first season was disrupted badly by a hamstring injury. But last season he was at the centre of many of the team’s better moments. When relegation was confirmed he posted online: \"West Ham United is too big, too special, and too powerful to stay down for long. The comeback starts now.\" But whether he will be part of that comeback attempt remains to be seen; plenty of rival clubs have shown an interest. Born in Rotterdam, he joined Feynoord’s academy in 2008, and caught the eye during a loan spell at ADO Den Haag. Away from football, he’s a big basketball fan. “I love to play on a basketball court because I love watching NBA,” he said in 2024. “My favourite players are LeBron James and Stephen Curry, both all-time greats, and I always try to replicate their shots when I’m on court.”"}, special: "Basketball lover" },
];

